using UnityEngine;using System.Collections.Generic;
public class MedicalCrawlingExile:MonoBehaviour {
 public MedicalInterior interior;public Material bloodMaterial;public bool started,stopped;public int marks;public float elapsed;WoodlandAnatomy body;Transform hips;Dictionary<string,Transform> bones=new Dictionary<string,Transform>();Dictionary<string,Quaternion> rests=new Dictionary<string,Quaternion>();float lastMark;Transform pool;
 void Start(){if(!interior)interior=Object.FindFirstObjectByType<MedicalInterior>();body=GetComponent<WoodlandAnatomy>();body.enabled=false;body.ragdoll=null;body.condition.blood=36;body.Region(BodyRegion.Abdomen).externalBleed=.6f;foreach(var a in GetComponentsInChildren<Animator>())a.enabled=false;foreach(var t in GetComponentsInChildren<Transform>()){bones[t.name]=t;rests[t.name]=t.localRotation;}hips=Bone("Hips");Pose(0);Mark(.24f);}
 Transform Bone(string n){bones.TryGetValue("mixamorig:"+n,out var b);return b;}
 // Two-bone inverse kinematics preserves bone lengths and uses explicit elbow/knee poles.
 void Solve(string upper,string lower,string end,Vector3 target,Vector3 pole){var a=Bone(upper);var b=Bone(lower);var c=Bone(end);if(!a||!b||!c)return;float l1=Vector3.Distance(a.position,b.position),l2=Vector3.Distance(b.position,c.position);var delta=target-a.position;float d=Mathf.Clamp(delta.magnitude,Mathf.Abs(l1-l2)+.005f,l1+l2-.005f);var axis=delta.normalized;var bend=Vector3.ProjectOnPlane(pole-a.position,axis).normalized;if(bend.sqrMagnitude<.01f)bend=Vector3.right;float along=(l1*l1+d*d-l2*l2)/(2*d);var elbow=a.position+axis*along+bend*Mathf.Sqrt(Mathf.Max(0,l1*l1-along*along));a.rotation=Quaternion.FromToRotation(b.position-a.position,elbow-a.position)*a.rotation;b.rotation=Quaternion.FromToRotation(c.position-b.position,target-b.position)*b.rotation;}
 void Pose(float t){foreach(var kv in rests)if(bones[kv.Key])bones[kv.Key].localRotation=kv.Value;if(!hips)return;float floor=interior.transform.position.y+.085f;var center=hips.position;for(int n=0;n<2;n++){string side=n==0?"Left":"Right";float sign=n==0?1:-1;float phase=Mathf.Repeat(t/2.5f+n*.5f,1);float reach=phase<.65f?Mathf.Lerp(-.70f,-.43f,phase/.65f):Mathf.Lerp(-.43f,-.70f,Mathf.SmoothStep(0,1,(phase-.65f)/.35f));float lift=phase>.65f?Mathf.Sin((phase-.65f)/.35f*Mathf.PI)*.07f:0;var hand=new Vector3(center.x+sign*.23f,floor+lift,center.z+reach);Solve(side+"Arm",side+"ForeArm",side+"Hand",hand,new Vector3(center.x+sign*.52f,floor+.03f,center.z-.18f));var foot=new Vector3(center.x+sign*(n==0?.22f:.12f),floor+.025f,center.z+(n==0?.54f:.67f));Solve(side+"UpLeg",side+"Leg",side+"Foot",foot,new Vector3(center.x+sign*.38f,floor-.05f,center.z+.2f));}var head=Bone("Head");if(head)head.rotation=Quaternion.AngleAxis(35,Vector3.right)*head.rotation;}
 void Update(){if(!interior||!interior.owner)return;if(!started&&interior.owner.player.transform.position.z>24)started=true;if(!started)return;elapsed+=Time.deltaTime;body.Tick(Time.deltaTime);if(!stopped){stopped=elapsed>13||body.Dead;if(!stopped){float pull=Mathf.Max(0,Mathf.Sin(elapsed*Mathf.PI*2/2.5f));transform.position+=Vector3.back*(.19f*pull*Time.deltaTime);Pose(elapsed);}if(elapsed-lastMark>.9f){lastMark=elapsed;Mark(.17f);}}else{if(!pool)pool=Mark(.3f);pool.localScale=Vector3.Lerp(pool.localScale,new Vector3(.85f,.004f,.65f),Time.deltaTime*.08f);}}
 Transform Mark(float size){if(marks>=24)return pool;var g=GameObject.CreatePrimitive(PrimitiveType.Cylinder);g.name="Exile blood drag";Destroy(g.GetComponent<Collider>());g.transform.SetParent(interior.transform,true);g.transform.position=new Vector3(transform.position.x,interior.transform.position.y+.016f+marks*.00015f,(hips?hips.position.z:transform.position.z)-.05f);g.transform.localScale=new Vector3(size,.004f,size*1.8f);g.GetComponent<Renderer>().sharedMaterial=bloodMaterial;marks++;return g.transform;}
}
